// 42-tap direct-form FIR, 8-bit samples, UNROLLED -> shorter register delay
// (the long register-to-register path becomes a small inline multiply and
// add chain). Same transfer function as the referenced one (the exact
// functional form is independent of the order of the terms).
module firr42_v3 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:41];
    integer     i;
    reg  [23:0] acc;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 42; i = i + 1) xs[i] <= 8'd0;
            acc <= 24'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            acc <= 24'd0 + 24'd5 + (24'd10 * xs[1]) + (24'd17 * xs[2]) + (24'd26 * xs[3]) + (24'd37 * xs[4]) + (24'd50 * xs[5]) + (24'd65 * xs[6]) + (24'd82 * xs[7]) + (24'd101 * xs[8]) + (24'd122 * xs[9]) + (24'd145 * xs[10]) + (24'd170 * xs[11]) + (24'd197 * xs[12]) + (24'd226 * xs[13]) + (24'd257 * xs[14]) + (24'd290 * xs[15]) + (24'd325 * xs[16]) + (24'd362 * xs[17]) + (24'd401 * xs[18]) + (24'd442 * xs[19]) + (24'd485 * xs[20]) + (24'd530 * xs[21]) + (24'd577 * xs[22]) + (24'd626 * xs[23]) + (24'd677 * xs[24]) + (24'd730 * xs[25]) + (24'd785 * xs[26]) + (24'd842 * xs[27]) + (24'd901 * xs[28]) + (24'd962 * xs[29]) + (24'd1025 * xs[30]) + (24'd1090 * xs[31]) + (24'd1157 * xs[32]) + (24'd1226 * xs[33]) + (24'd1297 * xs[34]) + (24'd1370 * xs[35]) + (24'd1445 * xs[36]) + (24'd1522 * xs[37]) + (24'd1601 * xs[38]) + (24'd1682 * xs[39]) + (24'd1765 * xs[40]) + (24'd1850 * xs[41]);
            for (i = 1; i < 42; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule
